<?php
/*
Landing PATS Franquiciatarios
Telefono dinamico por token:
- Si el token pertenece a gerente/gestor activo: telefono del gestor.
- Si no hay token, no coincide o no tiene telefono: corporativo.
*/

require_once '../../varSQL/bd_pats.php';
require_once '../../varSQL/var_pats.php';

$cx = $conexionMod ?? $db_all2 ?? $db_all ?? null;

$tokenLanding = trim((string)($_GET['t'] ?? ''));

/* Telefono corporativo predeterminado */
$telefonoAsesor = '+52 222 343 4609';
$telefonoHref   = '+522223434609';
$telefonoWa     = '522223434609';
$tipoContacto   = 'CORPORATIVO';

/*
  Ruta actual de solicitud.
  Conserva token si viene en la landing.
*/
$solicitudFranquiciaBaseUrl = 'solicitud-franquiciatario';

function pats_landing_html($v): string
{
    return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8');
}

function pats_landing_normalizar_telefono(string $telDb, string &$telefonoAsesor, string &$telefonoHref, string &$telefonoWa): void
{
    $telDb = trim($telDb);

    if ($telDb === '') {
        return;
    }

    $telefonoAsesor = $telDb;

    $href = preg_replace('/[^0-9+]/', '', $telDb) ?: '';
    $wa   = preg_replace('/\D+/', '', $telDb) ?: '';

    if ($href !== '' && $href[0] !== '+') {
        $href = '+52' . $href;
    }

    if ($wa !== '' && strpos($wa, '52') !== 0) {
        $wa = '52' . $wa;
    }

    if ($href !== '') {
        $telefonoHref = $href;
    }

    if ($wa !== '') {
        $telefonoWa = $wa;
    }
}

function pats_landing_buscar_telefono_gestor(mysqli $cx, string $token): string
{
    $sql = "
        SELECT telefono
        FROM pats_gestores
        WHERE public_checkout_token = ?
          AND public_checkout_activo = 1
          AND activo = 1
        LIMIT 1
    ";

    $stmt = $cx->prepare($sql);

    if (!$stmt) {
        return '';
    }

    $stmt->bind_param('s', $token);
    $stmt->execute();

    $res = $stmt->get_result();

    if (!$res) {
        $stmt->close();
        return '';
    }

    $row = $res->fetch_assoc();
    $stmt->close();

    return trim((string)($row['telefono'] ?? ''));
}

if ($tokenLanding !== '' && $cx instanceof mysqli) {
    try {
        $telGestor = pats_landing_buscar_telefono_gestor($cx, $tokenLanding);

        if ($telGestor !== '') {
            pats_landing_normalizar_telefono($telGestor, $telefonoAsesor, $telefonoHref, $telefonoWa);
            $tipoContacto = 'GESTOR';
        }
    } catch (Throwable $e) {
        $tipoContacto = 'CORPORATIVO';
    }
}

$solicitudFranquiciaUrl = $solicitudFranquiciaBaseUrl;

if ($tokenLanding !== '') {
    $solicitudFranquiciaUrl .= '?t=' . rawurlencode($tokenLanding);
}

$telefonoAsesorSafe          = pats_landing_html($telefonoAsesor);
$telefonoHrefSafe            = pats_landing_html($telefonoHref);
$telefonoWaSafe              = pats_landing_html($telefonoWa);
$tokenLandingSafe            = pats_landing_html($tokenLanding);
$tipoContactoSafe            = pats_landing_html($tipoContacto);
$solicitudFranquiciaUrlSafe  = pats_landing_html($solicitudFranquiciaUrl);
?>
