,255,.10);box-shadow:inset 0 2px 6px rgba(0,0,0,.24);overflow:hidden}.bar-fill{height:100%;border-radius:999px;background:linear-gradient(90deg,#2f67ff,#6366f1 58%,#22c7df);box-shadow:0 0 18px rgba(47,103,255,.28);transition:width .35s ease}.recovery-msg{margin-top:1rem;font-size:.82rem;color:rgba(255,255,255,.72);line-height:1.65}.scenario-table{margin-top:2rem;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:28px;overflow:hidden;box-shadow:0 24px 54px rgba(0,0,0,.22)}.scenario-row,.scenario-head{display:grid;grid-template-columns:.7fr 1fr 1.2fr 1.2fr 1.2fr;gap:1rem;align-items:center;padding:1rem 1.2rem}.scenario-head{background:linear-gradient(90deg,#1B63FF,#6868F4);font-size:.66rem;font-weight:900;letter-spacing:.09em;text-transform:uppercase;color:rgba(255,255,255,.9)}.scenario-row{border-top:1px solid rgba(255,255,255,.10);color:rgba(255,255,255,.75);font-size:.84rem}.scenario-row strong{color:#fff}.scenario-row .mint{color:#58FCCE;font-weight:900}

    .income-info-grid{display:grid;gap:1rem;margin-top:3rem}.income-card .income-value{font-size:1.65rem;font-weight:900;letter-spacing:-.055em;line-height:1;color:var(--blue);margin-bottom:.55rem}.proc-step{padding-top:2rem}.proc-num{width:60px;height:60px;border-radius:20px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;font-weight:900;margin-bottom:1.1rem;color:#fff;background:linear-gradient(135deg,var(--blue),var(--indigo));box-shadow:var(--shadow-blue),inset 0 1px 0 rgba(255,255,255,.22)}.proc-step.final .proc-num{background:linear-gradient(135deg,#07142F,#2A1769);box-shadow:var(--shadow-dark)}

    .doc-item{display:flex;align-items:center;gap:1rem;padding:1.35rem}.doc-icon{width:44px;height:44px;border-radius:15px;display:flex;align-items:center;justify-content:center;flex-shrink:0;border:1px solid #C6D5FF;background:var(--blue-soft);color:var(--blue);box-shadow:0 10px 20px rgba(5,17,35,.08),inset 0 1px 0 rgba(255,255,255,.88)}.doc-icon svg{width:20px;height:20px}.doc-name{color:var(--ink);font-weight:900;font-size:.9rem;line-height:1.25}.doc-sub{color:var(--text-soft);font-size:.76rem;line-height:1.45;margin-top:.12rem}.doc-req{margin-left:auto;flex-shrink:0;display:inline-flex;align-items:center;justify-content:center;min-height:28px;padding:.32rem .74rem;border-radius:999px;background:#E5ECFF;color:var(--blue);border:1px solid #C7D5FF;font-size:.63rem;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.docs-note{margin-top:1.35rem;background:radial-gradient(circle at 90% 20%,rgba(20,184,200,.16),transparent 32%),linear-gradient(145deg,#061434,#111C50);border:1px solid rgba(255,255,255,.10);border-radius:22px;padding:1.25rem 1.35rem;color:rgba(255,255,255,.74);font-size:.84rem;line-height:1.7;box-shadow:var(--shadow-dark)}

    .faq-section{background:radial-gradient(circle at 12% 8%,rgba(88,252,206,.16),transparent 34%),radial-gradient(circle at 86% 18%,rgba(99,102,241,.22),transparent 36%),linear-gradient(135deg,#031028 0%,#071438 46%,#17175A 100%);color:#fff;position:relative;overflow:hidden;padding:6.6rem 0}.faq-section::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px);background-size:64px 64px;opacity:.15}.faq-shell{position:relative;z-index:1;max-width:1180px;margin:auto;display:grid;gap:2.4rem}.faq-header{max-width:760px;margin:0 auto;text-align:center}.faq-kicker{display:inline-flex;align-items:center;justify-content:center;padding:.55rem 1.1rem;border-radius:999px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.14);color:#AEB0FF;font-size:.72rem;font-weight:900;letter-spacing:.15em;text-transform:uppercase;margin-bottom:1.25rem}.faq-panel{width:min(100%,1080px);margin:0 auto;padding:1.25rem;border-radius:32px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);box-shadow:0 34px 80px rgba(0,0,0,.28),inset 0 1px 0 rgba(255,255,255,.08);backdrop-filter:blur(14px)}.faq-list{display:grid;gap:.78rem}.faq-item{border:1px solid rgba(255,255,255,.12);border-radius:22px;background:linear-gradient(145deg,rgba(255,255,255,.09),rgba(255,255,255,.045));box-shadow:0 16px 34px rgba(0,0,0,.18),inset 0 1px 0 rgba(255,255,255,.08);overflow:hidden}.faq-item[hidden]{display:none}.faq-question{width:100%;appearance:none;border:0;background:transparent;color:#fff;cursor:pointer;display:grid;grid-template-columns:44px minmax(0,1fr) 46px;align-items:center;gap:1rem;padding:1.25rem 1.35rem;text-align:left;font-family:var(--ff)}.faq-num{width:34px;height:34px;border-radius:13px;display:flex;align-items:center;justify-content:center;color:#58FCCE;background:rgba(88,252,206,.10);border:1px solid rgba(88,252,206,.22);font-size:.72rem;font-weight:900}.faq-q-text{font-size:.94rem;font-weight:900;line-height:1.35;letter-spacing:-.025em}.faq-chevron{width:38px;height:38px;border-radius:14px;display:flex;align-items:center;justify-content:center;color:#AEB0FF;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12);transition:.22s ease}.faq-chevron svg{width:18px;height:18px}.faq-item.open .faq-chevron{transform:rotate(180deg);color:#58FCCE;background:rgba(88,252,206,.10);border-color:rgba(88,252,206,.26)}.faq-answer{max-height:0;overflow:hidden;transition:max-height .32s ease}.faq-answer-inner{padding:0 5.2rem 1.35rem 5.15rem;max-width:920px;color:rgba(255,255,255,.72);font-size:.9rem;line-height:1.78}.faq-answer-inner ul,.faq-answer-inner ol{margin:.55rem 0 0 1rem;padding-left:.85rem}.faq-answer-inner li{margin:.28rem 0}.faq-answer-inner strong{color:#fff;font-weight:900}.faq-actions{display:flex;justify-content:center;margin-top:1.35rem}.faq-more-btn{appearance:none;border:1px solid rgba(88,252,206,.30);background:linear-gradient(135deg,rgba(88,252,206,.16),rgba(99,102,241,.16));color:#fff;border-radius:16px;padding:1rem 1.45rem;min-width:230px;display:inline-flex;align-items:center;justify-content:center;gap:.65rem;font-family:var(--ff);font-size:.88rem;font-weight:900;cursor:pointer;box-shadow:0 18px 38px rgba(0,0,0,.22),0 4px 0 rgba(88,252,206,.16),inset 0 1px 0 rgba(255,255,255,.12)}.faq-more-btn svg{width:17px;height:17px;transition:.22s ease}.faq-more-btn.expanded svg{transform:rotate(180deg)}

    .cta-section{background:radial-gradient(circle at 18% 24%,rgba(27,99,255,.24),transparent 30%),radial-gradient(circle at 82% 18%,rgba(20,184,200,.16),transparent 32%),linear-gradient(135deg,#061434 0%,#0D1A50 52%,#25116A 100%);color:#fff;text-align:center;padding:6.4rem 0;position:relative;overflow:hidden}.cta-section::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px);background-size:72px 72px;opacity:.16}.cta-inner{position:relative;z-index:1}.cta-pill{display:inline-flex;border:1px solid rgba(99,102,241,.28);background:rgba(99,102,241,.12);color:#AEB0FF;font-size:.72rem;font-weight:900;letter-spacing:.14em;text-transform:uppercase;padding:.55rem 1.1rem;border-radius:999px;margin-bottom:1.7rem}.cta-title{font-size:clamp(2.1rem,5vw,4.1rem);font-weight:900;line-height:1.05;color:#fff;letter-spacing:-.075em;margin-bottom:1.2rem}.cta-lead{color:rgba(255,255,255,.68);max-width:600px;margin:0 auto 2.4rem;line-height:1.85}.cta-actions{justify-content:center;margin-bottom:1.25rem}.cta-section .btn-secondary{background:rgba(255,255,255,.05);color:#fff;border-color:rgba(255,255,255,.18);box-shadow:0 14px 28px rgba(0,0,0,.12),0 4px 0 rgba(255,255,255,.08),inset 0 1px 0 rgba(255,255,255,.10)}.cta-note{color:rgba(255,255,255,.56);font-size:.76rem;letter-spacing:.03em}
    .footer{background:linear-gradient(180deg,#06101F 0%,#020813 100%);border-top:6px solid transparent;border-image:linear-gradient(90deg,var(--blue),var(--indigo),var(--teal)) 1;padding:3.8rem 0 1.5rem}.footer-grid{display:grid;gap:2.5rem;padding-bottom:2.5rem;border-bottom:1px solid rgba(255,255,255,.10)}.footer-brand .logo{font-size:1.28rem;font-weight:900;color:#fff;margin-bottom:.8rem;letter-spacing:-.055em}.footer-brand p,.footer-nav a,.footer-nav p{color:rgba(255,255,255,.58);font-size:.84rem;line-height:1.75}.footer-nav h4{color:#AEB0FF;font-size:.7rem;font-weight:900;letter-spacing:.12em;text-transform:uppercase;margin-bottom:1rem}.footer-nav ul{display:flex;flex-direction:column;gap:.65rem}.footer-phone{color:#AEB0FF!important;font-size:1rem!important;font-weight:900!important}.footer-bottom{display:flex;flex-wrap:wrap;justify-content:space-between;gap:.6rem;padding-top:1.25rem}.footer-bottom p{color:rgba(255,255,255,.48);font-size:.73rem}.reveal{opacity:0;transform:translateY(22px);transition:opacity .65s ease,transform .65s ease}.reveal.vis{opacity:1;transform:translateY(0)}

    @media(min-width:640px){.why-grid{grid-template-columns:repeat(2,1fr)}.docs-grid{grid-template-columns:repeat(2,1fr)}.income-info-grid{grid-template-columns:repeat(2,1fr)}.proc-steps{grid-template-columns:repeat(2,1fr)}.footer-grid{grid-template-columns:repeat(2,1fr)}}
    @media(min-width:860px){.nav-links{display:flex}.sim-grid{grid-template-columns:repeat(3,1fr)}}
    @media(min-width:900px){.hero-inner{grid-template-columns:minmax(0,1fr) 390px}.why-grid{grid-template-columns:repeat(3,1fr)}.model-grid{grid-template-columns:1fr 1fr}.footer-grid{grid-template-columns:1.8fr 1fr 1fr 1.4fr}}
    @media(min-width:1100px){.proc-steps{grid-template-columns:repeat(4,1fr)}.income-info-grid{grid-template-columns:repeat(4,1fr)}}
    @media(max-width:900px){.hero{background:radial-gradient(circle at 18% 18%,rgba(27,99,255,.08),transparent 34%),#F7F9FC}.hero::after{display:none}.hero-invest,.model-highlight{transform:none}.scenario-head,.scenario-row{grid-template-columns:1fr;gap:.35rem}.scenario-head{display:none}.scenario-row{font-size:.9rem}}
    @media(max-width:760px){.nav-inner{height:68px}.hero{padding-top:68px}.hero-inner{padding-top:3.4rem}.hero-title{font-size:clamp(2.35rem,12vw,4rem)}.hero-actions,.cta-actions{flex-direction:column}.btn-primary,.btn-secondary{width:100%}.doc-item{align-items:flex-start;flex-wrap:wrap}.doc-item>div:nth-child(2){flex:1;min-width:180px}.doc-req{margin-left:0}.faq-panel{padding:.85rem;border-radius:26px}.faq-question{grid-template-columns:38px minmax(0,1fr) 40px;gap:.75rem;padding:1rem}.faq-answer-inner{padding:0 1rem 1.15rem;max-width:none}.model-amount{font-size:3.1rem}.sim-card{padding:1.35rem;border-radius:26px}}
  </style>
</head>
<body>
  <header class="nav" id="navbar">
    <div class="nav-inner">
      <a href="#inicio" class="nav-logo" aria-label="Inicio PATS Franquiciatarios">PATS <em></em> Franquiciatarios</a>
      <nav class="nav-links" aria-label="Navegación principal">
        <a href="#por-que">¿Por qué?</a><a href="#modelo">Modelo</a><a href="#ingresos">Ingresos</a><a href="#proceso">Proceso</a><a href="#documentos">Requisitos</a><a href="#solicitar" class="nav-cta">Solicitar franquicia</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero" id="inicio">
      <div class="hero-inner container">
        <div class="hero-left">

          <h1 class="hero-title reveal">Lidera el negocio que <br /><span class="accent">revolucionará</span><br /> la salud en México.</h1>
          <p class="hero-lead reveal">Adquiere la franquicia Pasaporte a tu Salud y construye una red comercial con ingresos por distribuciones, ventas directas y comisiones recurrentes por pasaportes activos.</p>
      
          <div class="hero-actions reveal"><a href="#solicitar" class="btn-primary"><svg width="18" height="18" viewBox="0 0 24 24" fill="none"><path d="M9 12l2 2 4-4M21 12a9 9 0 11-18 0 9 9 0 0118 0z" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>Solicitar alta como franquiciatario</a><a href="#ingresos" class="btn-secondary">Ver escenarios de ingreso</a></div>
        </div>
        <aside class="hero-invest reveal" aria-label="Resumen de franquicia">
          <div><div class="inv-label">Inversión desde</div><div class="inv-amount accent">$1,000,000</div><div class="inv-sub">MXN · IVA INCLUIDO</div></div>
          <div class="inv-sep"></div>
          <div class="invest-list">
            <div class="invest-list-item"><span class="invest-check"><svg viewBox="0 0 24 24" fill="none"><path d="M6 12.5l4 4L18 8" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Ganancia por venta de distribuciones</div>
            <div class="invest-list-item"><span class="invest-check"><svg viewBox="0 0 24 24" fill="none"><path d="M6 12.5l4 4L18 8" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Ganancia por venta de pasaportes</div>
            <div class="invest-list-item"><span class="invest-check"><svg viewBox="0 0 24 24" fill="none"><path d="M6 12.5l4 4L18 8" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Comisiones recurrentes mensuales</div>
          </div>
        </aside>
      </div>
    </section>

    <section class="section why" id="por-que">
      <div class="container">
        <div class="sec-header"><span class="sec-label reveal">¿Por qué ser franquiciatario?</span><h2 class="sec-title reveal">Un modelo de negocio sostenible y escalable</h2><p class="sec-lead reveal">Pasaporte a tu Salud acerca servicios médicos privados de alta calidad mediante una red hospitalaria respaldada por Fifty Doctors, sin deducibles, sin coaseguro y sin preexistencias.</p></div>
        <div class="why-grid">
          <article class="why-card featured-blue reveal"><div class="wc-icon"><svg viewBox="0 0 24 24" fill="none"><path d="M12 2v20M2 12h20" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></div><h3>3 vías de ingreso</h3><p>Ingresos por venta de distribuciones, comisión mensual por pasaportes vendidos por distribuidores y comisión por ventas directas del franquiciatario.</p></article>
          <article class="why-card featured-dark reveal"><div class="wc-icon"><svg viewBox="0 0 24 24" fill="none"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" stroke="currentColor" stroke-width="1.5"/></svg></div><h3>Garantía Fifty Doctors</h3><p>Detrás de cada atención hay una red hospitalaria comprometida con el bienestar y la salud de los pacientes.</p></article>
          <article class="why-card reveal"><div class="wc-icon"><svg viewBox="0 0 24 24" fill="none"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z" stroke="currentColor" stroke-width="1.5"/><circle cx="12" cy="10" r="3" stroke="currentColor" stroke-width="1.5"/></svg></div><h3>Operación regional</h3><p>El franquiciatario opera a nivel regional, desarrollando su territorio, su red comercial y sus canales de captación.</p></article>
          <article class="why-card reveal"><div class="wc-icon"><svg viewBox="0 0 24 24" fill="none"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2M9 11a4 4 0 100-8 4 4 0 000 8zM23 21v-2a4 4 0 00-3-3.87" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg></div><h3>Mercado amplio</h3><p>Dirigido a familias, niños, jóvenes, adultos, adultos mayores y empresas que desean ofrecer salud como prestación.</p></article>
          <article class="why-card reveal"><div class="wc-icon"><svg viewBox="0 0 24 24" fill="none"><rect x="2" y="3" width="20" height="14" rx="2" stroke="currentColor" stroke-width="1.5"/><path d="M8 21h8M12 17v4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg></div><h3>Herramientas de gestión</h3><p>Acceso a plataforma, control de actividad comercial, reportes, capacitación, materiales y uso autorizado de marca.</p></article>
          <article class="why-card reveal"><div class="wc-icon"><svg viewBox="0 0 24 24" fill="none"><path d="M3 12h18M5 12a7 7 0 0114 0 7 7 0 01-14 0zM12 5v14" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg></div><h3>Expansión nacional</h3><p>El programa proyecta atención a nivel nacional, abriendo nuevas oportunidades de crecimiento territorial.</p></article>
        </div>
      </div>
    </section>

    <section class="section dark-section" id="modelo">
      <div class="container">
        <div class="model-grid">
          <div><span class="sec-label reveal">Modelo de franquicia</span><h2 class="sec-title reveal">Una franquicia con ingresos recurrentes</h2><p class="sec-lead reveal">Como franquiciatario, puedes generar ingresos a través de la venta de distribuciones, de pasaportes vendidos por tus distribuidores y de tus propias ventas directas al usuario final.</p>
            <div class="route-list">
              <article class="route-card reveal"><span class="route-pill">Venta de distribuciones</span><div class="route-value">$10,000 MXN</div><h3>Ganancia por distribución en tu región</h3><p>Cada distribución tiene un valor de $20,000 MXN. Por cada distribución vendida dentro de tu región, recibes una ganancia directa de $10,000 MXN. Fuera de tu estado, la ganancia directa es de $5,000 MXN.</p></article>
              <article class="route-card reveal"><span class="route-pill">Pasaportes por distribuidores</span><div class="route-value">$20 MXN/mes</div><h3>Por cada pasaporte activo vendido por distribuidores de tu red</h3><p>El distribuidor recibe $80 MXN mensuales y tu como franquiciatario recibes $20 MXN mensuales por cada pasaporte activo vendido por tu red.</p></article>
              <article class="route-card reveal"><span class="route-pill">Venta directa</span><div class="route-value">$100 MXN/mes</div><h3>Por cada pasaporte vendido directamente</h3><p>Cuando el franquiciatario vende directamente al usuario, recibe $100 MXN mensuales por cada pasaporte activo.</p></article>
            </div>
          </div>
          <div class="model-highlight reveal"><div class="model-label">Ruta de recuperación</div><div class="model-amount">5 meses</div><div class="model-note">50 distribuciones, pasaportes vendidos por distribuidores y ventas directas de pasaportes permiten alcanzar un ingreso acumulado de $1,000,000 MXN al quinto mes. La simulación depende del desempeño comercial real mes a mes.</div></div>
        </div>
      </div>
    </section>

    <section class="section" id="ingresos">
      <div class="container">
        <div class="sec-header"><span class="sec-label reveal">Escenarios de ingresos</span><h2 class="sec-title reveal">Calcula tu potencial como franquiciatario</h2><p class="sec-lead reveal">Ajusta las variables y visualiza ingresos por distribuciones, comisiones recurrentes y recuperación estimada de inversión.</p></div>
        <div class="sim-card reveal">
          <div class="sim-grid">
            <div class="sim-control"><div class="sim-top"><span class="sim-label">Distribuciones vendidas</span><span class="sim-value" id="dist-val">50</span></div><input type="range" id="sl-dist" min="0" max="120" value="50" step="1" /></div>
            <div class="sim-control"><div class="sim-top"><span class="sim-label">Pasaportes vía distribuidores</span><span class="sim-value" id="pd-val">225</span></div><input type="range" id="sl-pd" min="0" max="5000" value="225" step="25" /></div>
            <div class="sim-control"><div class="sim-top"><span class="sim-label">Pasaportes venta directa</span><span class="sim-value" id="direct-val">50</span></div><input type="range" id="sl-direct" min="0" max="1000" value="50" step="5" /></div>
          </div>
          <div class="sim-results">
