  <script>
    const nav=document.getElementById("navbar");window.addEventListener("scroll",()=>{nav.classList.toggle("scrolled",window.scrollY>20)},{passive:true});
    const obs=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("vis");obs.unobserve(entry.target)}})},{threshold:.1,rootMargin:"0px 0px -40px 0px"});document.querySelectorAll(".reveal").forEach(el=>obs.observe(el));
    document.querySelectorAll('a[href^="#"]').forEach(a=>{a.addEventListener("click",e=>{const target=document.querySelector(a.getAttribute("href"));if(!target)return;e.preventDefault();window.scrollTo({top:target.getBoundingClientRect().top+window.scrollY-84,behavior:"smooth"})})});
    (function(){const INV=1000000,DIST_COM=10000,PD_COM=20,DIRECT_COM=100;const fmt=n=>"$"+Math.round(n).toLocaleString("es-MX")+" MXN";const slDist=document.getElementById("sl-dist"),slPd=document.getElementById("sl-pd"),slDirect=document.getElementById("sl-direct");function update(){const d=parseInt(slDist.value,10),pd=parseInt(slPd.value,10),direct=parseInt(slDirect.value,10);const distIngreso=d*DIST_COM;const mensual=(pd*PD_COM)+(direct*DIRECT_COM);const anual=mensual*12;const totalYear=distIngreso+anual;const remaining=INV-distIngreso;let recup=remaining<=0?"Inmediata":(mensual>0?Math.ceil(remaining/mensual)+" meses":"—");const pct=Math.min(100,Math.round((totalYear/INV)*100));document.getElementById("dist-val").textContent=d.toLocaleString("es-MX");document.getElementById("pd-val").textContent=pd.toLocaleString("es-MX");document.getElementById("direct-val").textContent=direct.toLocaleString("es-MX");document.getElementById("r-dist").textContent=fmt(distIngreso);document.getElementById("r-mensual").textContent=fmt(mensual);document.getElementById("r-anual").textContent=fmt(anual);document.getElementById("r-recup").textContent=recup;document.getElementById("r-total").textContent=fmt(totalYear);document.getElementById("bar-fill").style.width=pct+"%";document.getElementById("bar-pct").textContent=pct+"%";document.getElementById("recovery-msg").textContent="Con "+d.toLocaleString("es-MX")+" distribuciones, "+pd.toLocaleString("es-MX")+" pasaportes vía distribuidores y "+direct.toLocaleString("es-MX")+" ventas directas, el ingreso estimado de primer año es "+fmt(totalYear)+"."}if(slDist&&slPd&&slDirect){[slDist,slPd,slDirect].forEach(el=>el.addEventListener("input",update));update()}})();
    (function(){const faqItems=document.querySelectorAll(".faq-item"),moreBtn=document.getElementById("faq-more-btn"),extraItems=document.querySelectorAll(".faq-extra");function closeItem(item){const btn=item.querySelector(".faq-question"),answer=item.querySelector(".faq-answer");item.classList.remove("open");if(btn)btn.setAttribute("aria-expanded","false");if(answer)answer.style.maxHeight="0px"}function openItem(item){const btn=item.querySelector(".faq-question"),answer=item.querySelector(".faq-answer");item.classList.add("open");if(btn)btn.setAttribute("aria-expanded","true");if(answer)answer.style.maxHeight=answer.scrollHeight+"px"}faqItems.forEach(item=>{const btn=item.querySelector(".faq-question");if(!btn)return;btn.addEventListener("click",()=>{const isOpen=item.classList.contains("open");faqItems.forEach(other=>{if(other!==item)closeItem(other)});isOpen?closeItem(item):openItem(item)})});document.querySelectorAll(".faq-item.open").forEach(openItem);if(moreBtn){moreBtn.addEventListener("click",()=>{const expanded=moreBtn.classList.toggle("expanded");moreBtn.setAttribute("aria-expanded",expanded?"true":"false");extraItems.forEach(item=>{item.hidden=!expanded;if(!expanded)closeItem(item)});const label=moreBtn.querySelector("span");if(label)label.textContent=expanded?"Ver menos preguntas":"Ver todas las preguntas"})}window.addEventListener("resize",()=>{document.querySelectorAll(".faq-item.open .faq-answer").forEach(answer=>{answer.style.maxHeight=answer.scrollHeight+"px"})},{passive:true})})();
  </script>
